3:import java.math.BigDecimal;
4:import java.math.RoundingMode;
5:import java.text.DecimalFormat;
6:import java.text.DecimalFormatSymbols;
7:import java.util.Locale;
8:
9:/** KRW arithmetic shared by settlement and reporting. */
10:public final class Money {
11:    private static final BigDecimal TEN_THOUSAND = BigDecimal.valueOf(10_000);
12:
13:    private Money() {}
14:
15:    /** foreign amount x rate / unit, rounded to whole won (acquirer contract: half-up). */
16:    public static long toKrw(BigDecimal amount, BigDecimal rate, int unit) {
17:        return amount.multiply(rate)
18:                .divide(BigDecimal.valueOf(unit), 0, RoundingMode.HALF_UP)
19:                .longValueExact();
20:    }
21:
22:    /** Commission on gross KRW; partner contract truncates fractional won. */
23:    public static long fee(long grossKrw, int feeBps) {
24:        if (grossKrw <= 0 || feeBps <= 0) return 0;
25:        return BigDecimal.valueOf(grossKrw)
26:                .multiply(BigDecimal.valueOf(feeBps))
27:                .divide(TEN_THOUSAND, 0, RoundingMode.DOWN)
28:                .longValueExact();
29:    }
30:
31:    public static String won(long krw) {
32:        DecimalFormat f = new DecimalFormat("#,##0", DecimalFormatSymbols.getInstance(Locale.ROOT));
33:        return f.format(krw);
34:    }
35:
36:    public static String rate(BigDecimal rate) {
37:        DecimalFormat f = new DecimalFormat("#,##0.00", DecimalFormatSymbols.getInstance(Locale.ROOT));
38:        return f.format(rate);
39:    }
40:}

